#define _CRT_SECURE_NO_WARNINGS
#include "aervault.h"
#include "aervault_diag.h"
#include "aervault_history.h"
#include "aervault_journal.h"
#include "aervault_nor.h"
#include "aervault_queue.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BYTES 16384u
#define ASSERT(x) do { if (!(x)) { fprintf(stderr,"module fault failure %s point=%u mode=%u line=%d: %s\n",g_case,g_point,g_mode,__LINE__,#x); return 1; } } while(0)
static const char *g_case="init";
static unsigned g_point,g_mode;
static unsigned long g_scenarios;

typedef struct { uint8_t durable[BYTES],live[BYTES];size_t size;unsigned op,fail_at,mode; } sim_flash;
static void sim_init(sim_flash*m,size_t n){memset(m,0xff,sizeof(*m));m->size=n;m->op=0;m->fail_at=0;m->mode=0;}
static int sim_trip(sim_flash*m){return ++m->op==m->fail_at;}
static int sim_read(void*c,uint32_t off,void*out,size_t n){sim_flash*m=c;if((uint64_t)off+n>m->size)return -1;memcpy(out,m->live+off,n);return 0;}
static int sim_program(void*c,uint32_t off,const void*data,size_t n){sim_flash*m=c;const uint8_t*p=data;size_t lim=n,i;int fail;if((uint64_t)off+n>m->size)return -1;fail=sim_trip(m);if(fail&&m->mode==0)return -71;if(fail&&m->mode==1)lim=n/2u;for(i=0;i<lim;i++){if((m->live[off+i]&p[i])!=p[i])return -2;m->live[off+i]&=p[i];}if(fail)memcpy(m->durable+off,m->live+off,lim);return fail?-72:0;}
static int sim_erase(void*c,uint32_t off,size_t n){sim_flash*m=c;size_t lim=n;int fail;if((uint64_t)off+n>m->size)return -1;fail=sim_trip(m);if(fail&&m->mode==0)return -73;if(fail&&m->mode==1)lim=n/2u;memset(m->live+off,0xff,lim);if(fail)memcpy(m->durable+off,m->live+off,lim);return fail?-74:0;}
static int sim_sync(void*c){sim_flash*m=c;size_t n=m->size;int fail=sim_trip(m);if(fail&&m->mode==0)return -75;if(fail&&m->mode==1)n/=2u;memcpy(m->durable,m->live,n);return fail?-76:0;}
static void sim_crash(sim_flash*m){memcpy(m->live,m->durable,m->size);m->op=0;m->fail_at=0;m->mode=0;}

typedef struct {sim_flash media;av_journal_io io;av_journal_layout layout;av_journal journal;uint8_t work[1024];} fixture;
static int fx_format(fixture*f){sim_init(&f->media,8192);f->io.ctx=&f->media;f->io.read=sim_read;f->io.program=sim_program;f->io.erase=sim_erase;f->io.sync=sim_sync;f->layout.bank_offset[0]=0;f->layout.bank_offset[1]=4096;f->layout.bank_size=4096;f->layout.erase_size=256;f->layout.program_size=4;f->layout.erased_value=0xff;if(av_journal_format(&f->journal,&f->io,&f->layout,f->work,sizeof f->work)!=AV_JOURNAL_OK)return 0;memcpy(f->media.durable,f->media.live,f->media.size);f->media.op=0;return 1;}
static av_journal_status fx_reopen(fixture*f){sim_crash(&f->media);memset(f->work,0,sizeof f->work);return av_journal_mount(&f->journal,&f->io,&f->layout,f->work,sizeof f->work);}

static int queue_base(fixture*f,av_queue*q,av_queue_item*items,uint64_t*first,uint64_t*pending){if(!fx_format(f)||av_queue_open(q,&f->journal,items,8)!=AV_JOURNAL_OK)return 0;if(av_queue_push(q,"confirmed",9,first)!=AV_JOURNAL_OK||av_queue_push(q,"pending",7,pending)!=AV_JOURNAL_OK||av_queue_ack(q,*first)!=AV_JOURNAL_OK)return 0;memcpy(f->media.durable,f->media.live,f->media.size);f->media.op=0;return 1;}
static int queue_check(fixture*f,uint64_t first,uint64_t pending,uint64_t optional,int allow_optional){av_queue q;av_queue_item items[8];uint64_t id;char data[16];size_t n;av_journal_status j=fx_reopen(f),s;if(j!=AV_JOURNAL_OK&&j!=AV_JOURNAL_TORN){fprintf(stderr,"queue mount=%d\n",j);return 0;}s=av_queue_open(&q,&f->journal,items,8);if(s!=AV_JOURNAL_OK&&s!=AV_JOURNAL_TORN){fprintf(stderr,"queue open=%d\n",s);return 0;}if(!q.ready||q.count<1||q.items[0].id!=pending){fprintf(stderr,"queue state ready=%u count=%zu first=%llu expected=%llu\n",q.ready,q.count,(unsigned long long)(q.count?q.items[0].id:0),(unsigned long long)pending);return 0;}if(allow_optional){if(q.count>2)return 0;if(q.count==2&&q.items[1].id!=optional){fprintf(stderr,"queue optional=%llu expected=%llu\n",(unsigned long long)q.items[1].id,(unsigned long long)optional);return 0;}}else if(q.count!=1)return 0;if(av_queue_peek(&q,&id,data,sizeof data,&n)!=AV_JOURNAL_OK||id!=pending||n!=7||memcmp(data,"pending",7)){fprintf(stderr,"queue peek id=%llu len=%zu\n",(unsigned long long)id,n);return 0;}(void)first;return 1;}
static int q_push_at(unsigned point,unsigned mode){fixture f;av_queue q;av_queue_item items[8];uint64_t first,pending,new_id,next;av_journal_status s;g_case="queue-enqueue";g_point=point;g_mode=mode;ASSERT(queue_base(&f,&q,items,&first,&pending));next=av_journal_next_sequence(&f.journal);f.media.fail_at=point;f.media.mode=mode;s=av_queue_push(&q,"new",3,&new_id);ASSERT(s==AV_JOURNAL_IO);ASSERT(queue_check(&f,first,pending,next,1));g_scenarios++;return 0;}
static int q_ack_at(unsigned point,unsigned mode){fixture f;av_queue q;av_queue_item items[8];uint64_t first,pending,id;char data[16];size_t n=0;av_journal_status s;g_case="queue-ack";g_point=point;g_mode=mode;ASSERT(queue_base(&f,&q,items,&first,&pending));f.media.fail_at=point;f.media.mode=mode;s=av_queue_ack(&q,pending);ASSERT(s==AV_JOURNAL_IO);s=fx_reopen(&f);ASSERT(s==AV_JOURNAL_OK||s==AV_JOURNAL_TORN);s=av_queue_open(&q,&f.journal,items,8);ASSERT(s==AV_JOURNAL_OK||s==AV_JOURNAL_TORN);ASSERT(q.ready&&q.count<=1);if(q.count){ASSERT(q.items[0].id==pending&&q.items[0].id!=first);ASSERT(av_queue_peek(&q,&id,data,sizeof data,&n)==AV_JOURNAL_OK&&id==pending&&n==7);}g_scenarios++;return 0;}
static int q_compact_at(unsigned point,unsigned mode){fixture f;av_queue q;av_queue_item items[8];uint64_t first,pending;av_journal_status s;g_case="queue-compact";g_point=point;g_mode=mode;ASSERT(queue_base(&f,&q,items,&first,&pending));f.media.fail_at=point;f.media.mode=mode;s=av_queue_compact(&q);ASSERT(s==AV_JOURNAL_IO);ASSERT(queue_check(&f,first,pending,0,0));g_scenarios++;return 0;}

typedef struct {uint8_t bytes[2][2][128];size_t len[2][2];} obj_media;
typedef struct {obj_media media;av_backend backend;av_object_rule rules[2];av_config config;av_context context;uint8_t work[192];} app;
static int obj_idx(uint32_t id){return id==101?0:id==202?1:-1;}
static int obj_read(void*c,uint32_t id,unsigned slot,uint8_t*out,size_t cap,size_t*n){obj_media*m=c;int x=obj_idx(id);if(x<0||slot>1)return -1;if(!m->len[x][slot])return 1;if(m->len[x][slot]>cap)return -2;memcpy(out,m->bytes[x][slot],m->len[x][slot]);*n=m->len[x][slot];return 0;}
static int obj_replace(void*c,uint32_t id,unsigned slot,const uint8_t*p,size_t n){obj_media*m=c;int x=obj_idx(id);if(x<0||slot>1||n>sizeof m->bytes[0][0])return -1;memcpy(m->bytes[x][slot],p,n);m->len[x][slot]=n;return 0;}
static int obj_valid(void*c,uint32_t id){(void)c;return obj_idx(id)>=0;}
static int tag_fn(void*c,const uint8_t*p,size_t n,uint8_t out[AV_TAG_BYTES]){uint32_t h=2166136261u;size_t i;(void)c;for(i=0;i<n;i++)h=(h^p[i])*16777619u;for(i=0;i<AV_TAG_BYTES;i++)out[i]=(uint8_t)(h>>(8u*(i%4u)));return 0;}
static void app_open(app*a,const obj_media*saved){memset(a,0,sizeof(*a));if(saved)a->media=*saved;a->backend.ctx=&a->media;a->backend.read=obj_read;a->backend.replace=obj_replace;a->backend.validate_id=obj_valid;memset(a->rules,0,sizeof a->rules);a->rules[0].id=101;a->rules[0].identity[0]=0xa1;a->rules[0].schema=1;a->rules[0].policy=AV_RECOVERABLE;a->rules[0].payload_limit=16;a->rules[1].id=202;a->rules[1].identity[0]=0xb2;a->rules[1].schema=1;a->rules[1].policy=AV_RECOVERABLE;a->rules[1].payload_limit=16;a->config.backend=&a->backend;a->config.objects=a->rules;a->config.object_count=2;a->config.work=a->work;a->config.work_size=sizeof a->work;a->config.tag=tag_fn;a->config.tag_ctx=NULL;}
static int app_start(app*a){av_error e;if(av_open(&a->context,&a->config)!=AV_OK)return 0;if(av_provision_id(&a->context,101,"A0",2,&e)!=AV_OK||av_put(&a->context,101,"A1",2,&e)!=AV_OK||av_provision_id(&a->context,202,"B0",2,&e)!=AV_OK||av_put(&a->context,202,"B1",2,&e)!=AV_OK)return 0;return 1;}
static int app_set(app*a,uint32_t id,const char*v){return av_put(&a->context,id,v,2,NULL)==AV_OK;}
static int app_value(app*a,uint32_t id,const char*v,uint64_t revision){uint8_t b[8];size_t n=0;uint64_t r=0;av_status s=av_get(&a->context,id,b,sizeof b,&n,NULL);if(s!=AV_OK||n!=2||memcmp(b,v,2)){fprintf(stderr,"app value id=%u status=%d n=%zu got=%02x%02x expected=%s\n",id,(int)s,n,n?b[0]:0,n>1?b[1]:0,v);return 0;}s=av_get_revision(&a->context,id,&r,NULL);if(s!=AV_OK||r!=revision){fprintf(stderr,"app revision id=%u status=%d rev=%llu expected=%llu\n",id,(int)s,(unsigned long long)r,(unsigned long long)revision);return 0;}return 1;}
typedef struct {uint64_t seq[16];uint32_t id[16];uint64_t rev[16];size_t n;} hist_seen;
static int hist_visit(void*c,const av_journal_record*r,const uint8_t*p){hist_seen*s=c;if(r->type==0x3001u){if(r->length<12||s->n==16)return 1;s->seq[s->n]=r->sequence;s->id[s->n]=(uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);s->rev[s->n]=0;for(unsigned i=0;i<8;i++)s->rev[s->n]|=(uint64_t)p[4+i]<<(8u*i);s->n++;}return 0;}
static int history_base(fixture*f,app*a,av_history*h,uint8_t hw[128],uint64_t seqs[4]){if(!fx_format(f))return 0;app_open(a,NULL);if(!app_start(a))return 0;if(av_history_init(h,&f->journal,hw,128,4)!=AV_JOURNAL_OK)return 0;if(av_history_checkpoint(h,&a->context,101,&seqs[0])!=AV_JOURNAL_OK||av_history_checkpoint(h,&a->context,202,&seqs[1])!=AV_JOURNAL_OK)return 0;if(!app_set(a,101,"A2")||!app_set(a,202,"B2"))return 0;memcpy(f->media.durable,f->media.live,f->media.size);f->media.op=0;return 1;}
static int h_checkpoint_at(unsigned point,unsigned mode,uint32_t target){fixture f;app a,b;av_history h,h2;uint8_t hw[128],hw2[128],out[32];uint64_t seqs[4],rev;size_t n;av_journal_status rc;hist_seen seen;g_case="history-checkpoint";g_point=point;g_mode=mode;ASSERT(history_base(&f,&a,&h,hw,seqs));obj_media saved=a.media;f.media.fail_at=point;f.media.mode=mode;rc=av_history_checkpoint(&h,&a.context,target,&seqs[2]);ASSERT(rc==AV_JOURNAL_IO);rc=fx_reopen(&f);ASSERT(rc==AV_JOURNAL_OK||rc==AV_JOURNAL_TORN);app_open(&b,&saved);ASSERT(av_open(&b.context,&b.config)==AV_OK);ASSERT(app_value(&b,101,"A2",4)&&app_value(&b,202,"B2",4));ASSERT(av_history_init(&h2,&f.journal,hw2,sizeof hw2,4)==AV_JOURNAL_OK);memset(&seen,0,sizeof seen);rc=av_journal_scan(&f.journal,hist_visit,&seen);ASSERT(rc==AV_JOURNAL_OK||rc==AV_JOURNAL_TORN);ASSERT(seen.n==2||seen.n==3);ASSERT(seen.id[0]==101&&seen.id[1]==202);if(seen.n==3)ASSERT(seen.id[2]==target&&seen.rev[2]==4);rc=av_history_latest(&h2,101,&rev,out,sizeof out,&n);ASSERT(rc==AV_JOURNAL_OK||rc==AV_JOURNAL_TORN);if(rc==AV_JOURNAL_TORN)ASSERT(av_history_compact(&h2)==AV_JOURNAL_OK);ASSERT(av_history_latest(&h2,101,&rev,out,sizeof out,&n)==AV_JOURNAL_OK);ASSERT((rev==3&&memcmp(out,"A1",2)==0)||(rev==4&&memcmp(out,"A2",2)==0));rc=av_history_latest(&h2,202,&rev,out,sizeof out,&n);ASSERT(rc==AV_JOURNAL_OK);if(target==202)ASSERT((rev==3&&memcmp(out,"B1",2)==0)||(rev==4&&memcmp(out,"B2",2)==0));else ASSERT(rev==3&&memcmp(out,"B1",2)==0);g_scenarios++;return 0;}
static int history_compact_base(fixture*f,app*a,av_history*h,uint8_t hw[128],uint64_t seq[4]){if(!history_base(f,a,h,hw,seq))return 0;if(av_history_checkpoint(h,&a->context,101,&seq[2])!=AV_JOURNAL_OK||av_history_checkpoint(h,&a->context,202,&seq[3])!=AV_JOURNAL_OK)return 0;memcpy(f->media.durable,f->media.live,f->media.size);f->media.op=0;return 1;}
static int h_compact_at(unsigned point,unsigned mode){fixture f;app a,b;av_history h,h2;uint8_t hw[128],hw2[128],out[32];uint64_t seq[4],rev;size_t n;av_journal_status rc;hist_seen seen;g_case="history-compact-retention";g_point=point;g_mode=mode;ASSERT(history_compact_base(&f,&a,&h,hw,seq));obj_media saved=a.media;f.media.fail_at=point;f.media.mode=mode;rc=av_history_compact(&h);ASSERT(rc==AV_JOURNAL_IO);ASSERT(fx_reopen(&f)==AV_JOURNAL_OK);app_open(&b,&saved);ASSERT(av_open(&b.context,&b.config)==AV_OK);ASSERT(app_value(&b,101,"A2",4)&&app_value(&b,202,"B2",4));ASSERT(av_history_init(&h2,&f.journal,hw2,sizeof hw2,2)==AV_JOURNAL_OK);memset(&seen,0,sizeof seen);rc=av_journal_scan(&f.journal,hist_visit,&seen);ASSERT(rc==AV_JOURNAL_OK);ASSERT(seen.n==4||seen.n==2);if(seen.n==4)ASSERT(seen.seq[0]==seq[0]&&seen.seq[1]==seq[1]&&seen.seq[2]==seq[2]&&seen.seq[3]==seq[3]);else ASSERT(seen.seq[0]==seq[2]&&seen.seq[1]==seq[3]);ASSERT(av_history_latest(&h2,101,&rev,out,sizeof out,&n)==AV_JOURNAL_OK&&rev==4&&memcmp(out,"A2",2)==0);ASSERT(av_history_latest(&h2,202,&rev,out,sizeof out,&n)==AV_JOURNAL_OK&&rev==4&&memcmp(out,"B2",2)==0);g_scenarios++;return 0;}

static int diag_base(fixture*f,av_diag*d,uint64_t*ids){av_diag_record r;if(!fx_format(f)||av_diag_init(d,&f->journal,2)!=AV_JOURNAL_OK)return 0;memset(&r,0,sizeof r);r.length=2;r.payload[0]=0x5a;r.payload[1]=0xc3;r.event=1;if(av_diag_write(d,&r,&ids[0])!=AV_JOURNAL_OK)return 0;r.event=2;if(av_diag_write(d,&r,&ids[1])!=AV_JOURNAL_OK)return 0;memcpy(f->media.durable,f->media.live,f->media.size);f->media.op=0;return 1;}
static int d_write_at(unsigned point,unsigned mode){fixture f;av_diag d,d2;uint64_t ids[3],seq;av_diag_record r,got;av_journal_status rc;g_case="diag-write";g_point=point;g_mode=mode;ASSERT(diag_base(&f,&d,ids));ids[2]=av_journal_next_sequence(&f.journal);memset(&r,0,sizeof r);r.event=3;r.length=2;r.payload[0]=0xde;r.payload[1]=0xad;f.media.fail_at=point;f.media.mode=mode;rc=av_diag_write(&d,&r,&seq);ASSERT(rc==AV_JOURNAL_IO);ASSERT(f.media.op==point);av_journal_status mount=fx_reopen(&f);ASSERT(mount==AV_JOURNAL_OK||mount==AV_JOURNAL_TORN);ASSERT(av_diag_init(&d2,&f.journal,3)==AV_JOURNAL_OK);if(mount==AV_JOURNAL_TORN)ASSERT(av_diag_compact(&d2)==AV_JOURNAL_OK);ASSERT(av_diag_read(&d2,ids[0],&got)==AV_JOURNAL_OK&&got.event==1);ASSERT(av_diag_read(&d2,ids[1],&got)==AV_JOURNAL_OK&&got.event==2);rc=av_diag_read(&d2,ids[2],&got);ASSERT(rc==AV_JOURNAL_FULL||(rc==AV_JOURNAL_OK&&got.event==3&&got.length==2&&got.payload[0]==0xde&&got.payload[1]==0xad));g_scenarios++;return 0;}
static int d_compact_at(unsigned point,unsigned mode){fixture f;av_diag d,d2;uint64_t ids[3];av_diag_record got;av_journal_status rc;g_case="diag-compact";g_point=point;g_mode=mode;ASSERT(diag_base(&f,&d,ids));{av_diag_record r;memset(&r,0,sizeof r);r.event=3;r.length=1;r.payload[0]=3;ASSERT(av_diag_write(&d,&r,&ids[2])==AV_JOURNAL_OK);}memcpy(f.media.durable,f.media.live,f.media.size);f.media.op=0;f.media.fail_at=point;f.media.mode=mode;rc=av_diag_compact(&d);ASSERT(rc==AV_JOURNAL_IO);ASSERT(fx_reopen(&f)==AV_JOURNAL_OK);ASSERT(av_diag_init(&d2,&f.journal,2)==AV_JOURNAL_OK);ASSERT(av_diag_read(&d2,ids[1],&got)==AV_JOURNAL_OK&&got.event==2);ASSERT(av_diag_read(&d2,ids[2],&got)==AV_JOURNAL_OK&&got.event==3);g_scenarios++;return 0;}
static int d_original_error(void){fixture f;av_diag d;av_diag_record r;av_journal_status primary,secondary;unsigned before;g_case="diag-secondary-error";g_point=1;g_mode=0;ASSERT(fx_format(&f));ASSERT(av_diag_init(&d,&f.journal,2)==AV_JOURNAL_OK);f.media.fail_at=1;primary=av_journal_append(&f.journal,0x7002,"FAIL",4,NULL);ASSERT(primary==AV_JOURNAL_IO);before=f.media.op;memset(&r,0,sizeof r);r.event=0xdead;secondary=av_diag_write(&d,&r,NULL);ASSERT(secondary==AV_JOURNAL_TORN);ASSERT(primary==AV_JOURNAL_IO);ASSERT(f.media.op==before);g_scenarios++;return 0;}

typedef struct {sim_flash *m;} driver_ctx;
static int drv_read(uint32_t o,void*p,uint32_t n,void*c){return sim_read(((driver_ctx*)c)->m,o,p,n);}
static int drv_write(uint32_t o,const void*p,uint32_t n,void*c){return sim_program(((driver_ctx*)c)->m,o,p,n);}
static int drv_erase(uint32_t o,uint32_t n,void*c){return sim_erase(((driver_ctx*)c)->m,o,n);}
static int drv_sync(void*c){return sim_sync(((driver_ctx*)c)->m);}
typedef struct {mflash_t flash;mflash_driver_t driver;mflash_partition_t parts[1];mflash_stats_t stats[1];driver_ctx dctx;av_nor nor;av_journal_io io;av_journal_layout layout;av_journal journal;uint8_t work[1024];} nor_fixture;
static int nor_bind(nor_fixture*n,sim_flash*m){n->dctx.m=m;n->driver.read=drv_read;n->driver.write=drv_write;n->driver.erase=drv_erase;n->driver.ctx=&n->dctx;if(mflash_init(&n->flash,&n->driver,n->parts,n->stats,1)!=MFLASH_OK)return 0;if(mflash_add_partition(&n->flash,"avtest",0,8192,256,4,MFLASH_TYPE_NOR,0)!=0)return 0;if(av_nor_bind(&n->nor,&n->flash,0,drv_sync,&n->dctx,&n->io,&n->layout)!=0)return 0;return 1;}
static int nor_format(nor_fixture*n,sim_flash*m){if(!nor_bind(n,m))return 0;if(av_journal_format(&n->journal,&n->io,&n->layout,n->work,sizeof n->work)!=AV_JOURNAL_OK)return 0;memcpy(m->durable,m->live,m->size);m->op=0;return 1;}
typedef struct {unsigned base,next;} raw_seen;
static int raw_visit(void*c,const av_journal_record*r,const uint8_t*p){raw_seen*s=c;if(r->type==0x7001u&&r->length==4){if(!memcmp(p,"BASE",4))s->base++;if(!memcmp(p,"NEXT",4))s->next++;}return 0;}
static int keep_all(void*c,const av_journal_record*r,const uint8_t*p){(void)c;(void)r;(void)p;return 1;}
static int nor_append_at(unsigned point,unsigned mode){sim_flash m;nor_fixture n,n2;raw_seen seen={0,0};av_journal_status rc;uint8_t other[4096];g_case="nor-append";g_point=point;g_mode=mode;sim_init(&m,8192);ASSERT(nor_format(&n,&m));ASSERT(av_journal_append(&n.journal,0x7001,"BASE",4,NULL)==AV_JOURNAL_OK);memcpy(m.durable,m.live,m.size);memcpy(other,m.durable+4096,sizeof other);m.op=0;m.fail_at=point;m.mode=mode;rc=av_journal_append(&n.journal,0x7001,"NEXT",4,NULL);ASSERT(rc==AV_JOURNAL_IO);ASSERT(memcmp(m.durable+4096,other,sizeof other)==0);sim_crash(&m);memset(&n2,0,sizeof n2);ASSERT(nor_bind(&n2,&m));memset(n2.work,0,sizeof n2.work);rc=av_journal_mount(&n2.journal,&n2.io,&n2.layout,n2.work,sizeof n2.work);ASSERT(rc==AV_JOURNAL_OK||rc==AV_JOURNAL_TORN);rc=av_journal_scan(&n2.journal,raw_visit,&seen);ASSERT(rc==AV_JOURNAL_OK||rc==AV_JOURNAL_TORN);ASSERT(seen.base==1&&seen.next<=1);g_scenarios++;return 0;}
static int nor_compact_at(unsigned point,unsigned mode){sim_flash m;nor_fixture n,n2;raw_seen seen={0,0};av_journal_status rc;uint8_t source[4096];g_case="nor-erase-program-compact";g_point=point;g_mode=mode;sim_init(&m,8192);ASSERT(nor_format(&n,&m));ASSERT(av_journal_append(&n.journal,0x7001,"BASE",4,NULL)==AV_JOURNAL_OK);ASSERT(av_journal_append(&n.journal,0x7001,"NEXT",4,NULL)==AV_JOURNAL_OK);memcpy(m.durable,m.live,m.size);memcpy(source,m.durable,4096);m.op=0;m.fail_at=point;m.mode=mode;rc=av_journal_compact(&n.journal,keep_all,NULL);ASSERT(rc==AV_JOURNAL_IO);ASSERT(memcmp(m.durable,source,sizeof source)==0);sim_crash(&m);memset(&n2,0,sizeof n2);ASSERT(nor_bind(&n2,&m));memset(n2.work,0,sizeof n2.work);rc=av_journal_mount(&n2.journal,&n2.io,&n2.layout,n2.work,sizeof n2.work);ASSERT(rc==AV_JOURNAL_OK);rc=av_journal_scan(&n2.journal,raw_visit,&seen);ASSERT(rc==AV_JOURNAL_OK&&seen.base==1&&seen.next==1);g_scenarios++;return 0;}

int main(int argc,char**argv){unsigned qpush=0,qack=0,qcompact=0,hwrite=0,hcompact=0,dwrite=0,dcompact=0,nwrite=0,ncompact=0,p,mode;fixture f;av_queue q;av_queue_item qi[8];uint64_t a,b;app core;av_history hist;uint8_t hw[128];uint64_t hs[4];av_diag diag;uint64_t ds[3];nor_fixture nor;sim_flash sm;FILE*report;const char*report_path=argc>1?argv[1]:"aervault-module-fault-results.json";g_case="measure";ASSERT(queue_base(&f,&q,qi,&a,&b));f.media.op=0;ASSERT(av_queue_push(&q,"extra",5,NULL)==AV_JOURNAL_OK);qpush=f.media.op;ASSERT(queue_base(&f,&q,qi,&a,&b));f.media.op=0;ASSERT(av_queue_ack(&q,b)==AV_JOURNAL_OK);qack=f.media.op;ASSERT(queue_base(&f,&q,qi,&a,&b));f.media.op=0;ASSERT(av_queue_compact(&q)==AV_JOURNAL_OK);qcompact=f.media.op;
 ASSERT(history_base(&f,&core,&hist,hw,hs));f.media.op=0;ASSERT(av_history_checkpoint(&hist,&core.context,101,NULL)==AV_JOURNAL_OK);hwrite=f.media.op;ASSERT(history_compact_base(&f,&core,&hist,hw,hs));f.media.op=0;ASSERT(av_history_compact(&hist)==AV_JOURNAL_OK);hcompact=f.media.op;
 ASSERT(diag_base(&f,&diag,ds));f.media.op=0;{av_diag_record r;memset(&r,0,sizeof r);r.event=9;ASSERT(av_diag_write(&diag,&r,NULL)==AV_JOURNAL_OK);}dwrite=f.media.op;ASSERT(diag_base(&f,&diag,ds));{av_diag_record r;memset(&r,0,sizeof r);r.event=3;ASSERT(av_diag_write(&diag,&r,NULL)==AV_JOURNAL_OK);}f.media.op=0;ASSERT(av_diag_compact(&diag)==AV_JOURNAL_OK);dcompact=f.media.op;
 sim_init(&sm,8192);ASSERT(nor_format(&nor,&sm));ASSERT(av_journal_append(&nor.journal,0x7001,"BASE",4,NULL)==AV_JOURNAL_OK);sm.op=0;ASSERT(av_journal_append(&nor.journal,0x7001,"NEXT",4,NULL)==AV_JOURNAL_OK);nwrite=sm.op;sm.op=0;ASSERT(av_journal_compact(&nor.journal,keep_all,NULL)==AV_JOURNAL_OK);ncompact=sm.op;
 for(mode=0;mode<3;mode++){for(p=1;p<=qpush;p++)if(q_push_at(p,mode))return 1;for(p=1;p<=qack;p++)if(q_ack_at(p,mode))return 1;for(p=1;p<=qcompact;p++)if(q_compact_at(p,mode))return 1;for(p=1;p<=hwrite;p++){if(h_checkpoint_at(p,mode,101)||h_checkpoint_at(p,mode,202))return 1;}for(p=1;p<=hcompact;p++)if(h_compact_at(p,mode))return 1;for(p=1;p<=dwrite;p++)if(d_write_at(p,mode))return 1;for(p=1;p<=dcompact;p++)if(d_compact_at(p,mode))return 1;for(p=1;p<=nwrite;p++)if(nor_append_at(p,mode))return 1;for(p=1;p<=ncompact;p++)if(nor_compact_at(p,mode))return 1;}if(d_original_error())return 1;
 report=fopen(report_path,"w");if(!report){perror("module fault report");return 2;}fprintf(report,"{\n  \"status\": \"PASS\",\n  \"queue_cases\": %u,\n  \"history_cases\": %u,\n  \"diagnostic_cases\": %u,\n  \"nor_adapter_cases\": %u,\n  \"total_cases\": %lu,\n  \"fault_modes\": [\"fail before mutation\",\"partial durable operation\",\"complete durable operation with error\"],\n  \"reset\": \"fresh public handles and cleared work buffers from preserved bytes\"\n}\n",(qpush+qack+qcompact)*3u,(hwrite*2u+hcompact)*3u,(dwrite+dcompact)*3u+1u,(nwrite+ncompact)*3u,g_scenarios);fclose(report);printf("module fault matrices PASS scenarios=%lu q=%u/%u/%u history=%u/%u diag=%u/%u nor=%u/%u\n",g_scenarios,qpush,qack,qcompact,hwrite,hcompact,dwrite,dcompact,nwrite,ncompact);return 0;}
